-- Patricia Powell (profileID=16) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Patricia Powell phrasings

SELECT p.argumentID, p.phrasingID, 16, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 16
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 16 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=16 AND targArgID IN (80,88,89,90,94,96,100,103,104,105,111,112,113,115,116,130,144,145,148,151,153,154,155,169,171,174,175,182,184,207,217,218,219,221,222,223,236,238,240,241,346,347,349,350,355,356,357,428,484,485,500,539,543,546,547,549,551,560,561,603,615,617,640,770,775,844,972,1005,1188,1197,1202,1229,1313,1314,1321,1345,1346,1347,1351,1357,1365,1380,1385,1440);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 16
SET pe.active = o.acceptance
WHERE pe.profileID = 16;

SELECT 'Done: endorsements for profileID=16' AS status;